#include <vector>
std::vector<int> buildNext(const std::string& p) {
    const int m = static_cast<int>(p.size());
    std::vector<int> next(m, -1);
    if (m == 0) return next;
    int i = 0, k = -1;
    while (i + 1 < m) {
        if (k == -1 || p[i] == p[k]) {
            ++i; ++k;
            next[i] = k;
        } else {
            k = next[k];
        }
    }
    return next;
}
\end{codeblock}

